function rtzip(array $files):string{$local='';$central='';$offset=0;foreach($files as $name=>$data){$crc=crc32($data);$size=strlen($data);$nameLength=strlen($name);$header=pack('VvvvvvVVVvv',0x04034b50,20,0,0,0,0,$crc,$size,$size,$nameLength,0).$name;$local.=$header.$data;$central.=pack('VvvvvvvVVVvvvvvVV',0x02014b50,20,20,0,0,0,0,$crc,$size,$size,$nameLength,0,0,0,0,0,$offset).$name;$offset+=strlen($header)+$size;}return $local.$central.pack('VvvvvVVv',0x06054b50,0,0,count($files),count($files),strlen($central),strlen($local),0);}
function rtseed(PDO $db):void{$sql=preg_replace('/^\s*--.*$/m','',file_get_contents(ROOT.'/database/seeds/002_technology_catalog.sql'));foreach(explode(';',$sql) as $statement)if(trim($statement)!=='')$db->exec($statement);}

